187	import java.sql.SQLException;
188	import shop.db.Dao;
189	import shop.domain.Order;
190	
191	/**
192	 * Something that happens when an order's payment is confirmed (and is undone if the paid order is cancelled).
193	 * Future effects (SMS, cashback points) are new implementations added to the list in {@link OrderService}.
194	 */
195	public interface PaidOrderEffect {
196	    void onPaid(Dao dao, Order order) throws SQLException;
197	
198	    void onPaidOrderCancelled(Dao dao, Order order) throws SQLException;
199	}
200	package shop.app;
201	
202	import java.sql.SQLException;
203	import shop.db.Dao;
204	import shop.domain.Order;
205	
206	/** Club credit goes into the customer's balance on payment and comes out on cancellation. */
207	public final class CreditEffect implements PaidOrderEffect {
208	    @Override
209	    public void onPaid(Dao dao, Order order) throws SQLException {
210	        dao.addCredit(order.cpf(), order.summary().nextPurchaseCredit());
211	    }
212	
213	    @Override
214	    public void onPaidOrderCancelled(Dao dao, Order order) throws SQLException {
215	        dao.addCredit(order.cpf(), order.summary().nextPurchaseCredit().negate());
216	    }
217	}
218	package shop.app;
219	
220	import java.sql.SQLException;
221	import shop.db.Dao;
222	import shop.domain.NotificationType;
223	import shop.domain.Order;
224	
225	public final class PaymentApprovedNoticeEffect implements PaidOrderEffect {
226	    private final Notifier notifier;
227	
228	    public PaymentApprovedNoticeEffect(Notifier notifier) {
229	        this.notifier = notifier;
230	    }
231	
232	    @Override
233	    public void onPaid(Dao dao, Order order) throws SQLException {
234	        notifier.notify(dao, order, NotificationType.PAYMENT_APPROVED);
235	    }
236	
237	    @Override
238	    public void onPaidOrderCancelled(Dao dao, Order order) {
239	        // the cancellation notice is sent for every cancellation by OrderService
240	    }
241	}
242	package shop.app;
243	
244	import java.sql.SQLException;
245	import java.util.UUID;
246	import shop.db.Dao;
247	import shop.domain.Notification;
248	import shop.domain.NotificationType;
249	import shop.domain.Order;
250	
251	/** Records customer notices for the support team (real e-mail comes later). */
252	public final class Notifier {
253	    public void notify(Dao dao, Order order, NotificationType type) throws SQLException {
254	        dao.insertNotification(new Notification(UUID.randomUUID().toString(), order.cpf(), type, order.id(), "NEW"));
255	    }
256	}

